1	// The home screen and the app's signature interaction: a blank page you can
2	// type on immediately. Swiping up files the page away (the note slides off the
3	// top) and a fresh blank page is ready underneath — same gesture as the
4	// original app. Notes land in Feed via the desktop-compatible core.
5	
6	import { Ionicons } from "@expo/vector-icons";
7	import { useNavigation } from "@react-navigation/native";
8	import type { NativeStackNavigationProp } from "@react-navigation/native-stack";
9	import { useEffect, useMemo, useRef, useState } from "react";
10	import {
11	  Keyboard,
12	  StyleSheet,
13	  Text,
14	  TextInput,
15	  useWindowDimensions,
16	  View,
17	} from "react-native";
18	import { Gesture, GestureDetector } from "react-native-gesture-handler";
19	import Animated, {
20	  Easing,
21	  runOnJS,
22	  useAnimatedStyle,
23	  useSharedValue,
24	  withSpring,
25	  withTiming,
26	} from "react-native-reanimated";
27	import { useSafeAreaInsets } from "react-native-safe-area-context";
28	
29	import * as core from "@typenotes/mobile-core/core-api";
30	
31	import { CaptureSession } from "../lib/capture";
32	import { useClearInstantParam, type RootStackParamList } from "../navigation";
33	import { useNotesStore } from "../state/notes-store";
34	import { useTheme } from "../theme";
35	import { DictationButton } from "../ui/dictation-button";
36	import { ToolbarButton } from "../ui/toolbar-button";
37	
38	const SWIPE_DISTANCE = 90;
39	const SWIPE_VELOCITY = -900;
40	
41	// The finger-driven swipe to the sync screen (same mechanics as the menu's
42	// swipe-to-capture in menu-screen.tsx): release past this fraction of the
43	// screen (or a faster leftward flick) commits, the page parallaxes left
44	// behind the incoming preview.
45	const SYNC_OPEN_PROGRESS = 0.3;
46	const SYNC_OPEN_VELOCITY = -500;
47	const SYNC_PARALLAX = 0.3;
48	
49	export const CaptureScreen = () => {
50	  const theme = useTheme();
51	  const insets = useSafeAreaInsets();
52	  const navigation =
53	    useNavigation<NativeStackNavigationProp<RootStackParamList>>();
54	  const { height, width } = useWindowDimensions();
55	
56	  const [text, setText] = useState("");
57	  const [pageKey, setPageKey] = useState(0);
58	  const [iconsVisible, setIconsVisible] = useState(true);
59	  const [recordingActive, setRecordingActive] = useState(false);
60	  const iconsOpacity = useSharedValue(1);
61	  const inputRef = useRef<TextInput>(null);
62	
63	  const session = useMemo(
64	    () =>
65	      new CaptureSession({
66	        createNote: async (content) => (await core.createNote({ content })).path,
67	        writeNote: core.writeNote,
68	        deleteNote: (path) => core.deleteItems([path]),
69	      }),
70	    []
71	  );
72	
73	  // Flush the draft when the screen loses focus (navigation away).
74	  useEffect(
75	    () => navigation.addListener("blur", () => void session.flush()),
76	    [navigation, session]
77	  );
78	
79	  // The menu's swipe may have pushed this page with animation:none (its
80	  // preview already played the transition) — flip the flag back once the
81	  // push settles so the later pop / back swipe animates natively.
82	  useClearInstantParam();
83	
84	  const translateY = useSharedValue(0);
85	
86	  // Wrap Keyboard.dismiss so the worklet captures this plain closure rather
87	  // than the bare method — passing Keyboard.dismiss straight to runOnJS makes
88	  // worklets try to copy its owner (KeyboardImpl), which it can't serialize.
89	  const dismissKeyboard = () => Keyboard.dismiss();
90	
91	  const commitPage = () => {
92	    void session.commit().then((path) => {
93	      if (path) {
94	        void useNotesStore.getState().refresh();
95	      }
96	    });
97	    // Remount the input so the new blank page appears with no text flash.
98	    setText("");
99	    setPageKey((key) => key + 1);
100	    translateY.value = 0;
101	    showIcons();
102	  };
103	
104	  const showIcons = () => {
105	    setIconsVisible(true);
106	    iconsOpacity.value = withTiming(1, { duration: 180 });
107	  };
108	
109	  const hideIcons = () => {
110	    setIconsVisible(false);
111	    iconsOpacity.value = withTiming(0, { duration: 180 });
112	  };
113	
114	  // A clear downward drag tucks the keyboard away (the input regains it on
115	  // the next tap). Runs alongside the swipe-up gesture, which claims only
116	  // upward drags.
117	  const dismissKeyboardPan = Gesture.Pan()
118	    .activeOffsetY(24)
119	    .failOffsetY(-12)
120	    .onStart(() => {
121	      runOnJS(dismissKeyboard)();
122	    });
123	
124	  // Conceptually the sync screen sits to the RIGHT of the capture page (the
125	  // menu is to the left): a clearly-leftward drag pulls it in with the
126	  // finger, exactly like the menu's swipe-to-capture — a preview overlay
127	  // (background + a replica of Sync's native header) rides the finger, and
128	  // committing pushes the real screen underneath it with animation:none.
129	  // Rightward drags stay with the native back swipe, vertical ones with the
130	  // page gestures. Sync's body is dynamic so the preview can't replicate it;
131	  // only the chrome matches and the content appears at the swap.
132	  const syncProgress = useSharedValue(0);
133	
134	  const syncDepthStyle = useAnimatedStyle(() => ({
135	    transform: [{ translateX: -width * SYNC_PARALLAX * syncProgress.value }],
136	  }));
137	  const syncDimStyle = useAnimatedStyle(() => ({
138	    opacity: 0.08 * syncProgress.value,
139	  }));
140	  const syncPreviewStyle = useAnimatedStyle(() => ({
141	    transform: [{ translateX: width * (1 - syncProgress.value) }],
142	    // Parked exactly one screen-width right; hide it whenever this gesture
143	    // isn't driving it or native pops (which parallax this whole screen)
144	    // would poke its edge into the frame — same trap as the menu's preview.
145	    opacity: syncProgress.value > 0 ? 1 : 0,
146	  }));
147	
148	  const openSyncBehindPreview = () => {
149	    navigation.navigate("Sync", { instant: true });
150	    // Drop the preview once the pushed screen is attached on top (no native
151	    // "attached" signal with animation:none — the delay outlives the mount).
152	    setTimeout(() => {
153	      syncProgress.value = 0;
154	    }, 400);
155	  };
156	
157	  const swipeToSync = Gesture.Pan()
158	    .activeOffsetX(-24)
159	    .failOffsetX(24)
160	    .failOffsetY([-24, 24])
161	    .onStart(() => {
162	      // The capture input stays mounted (and focused) beneath the pushed
163	      // screen and would otherwise keep the keyboard up over it.
164	      runOnJS(dismissKeyboard)();
165	    })
166	    .onUpdate((event) => {
167	      syncProgress.value = Math.min(1, Math.max(0, -event.translationX / width));
168	    })
169	    .onEnd((event) => {
170	      const shouldOpen =
171	        syncProgress.value > SYNC_OPEN_PROGRESS ||
172	        event.velocityX < SYNC_OPEN_VELOCITY;
173	      if (shouldOpen) {
174	        syncProgress.value = withTiming(
175	          1,
176	          { duration: 160, easing: Easing.out(Easing.cubic) },
177	          (finished) => {
178	            if (finished) {
179	              runOnJS(openSyncBehindPreview)();
180	            }
181	          }
182	        );
183	      } else {
184	        syncProgress.value = withTiming(0, { duration: 180 });
185	      }
186	    });
187	
188	  const pan = Gesture.Pan()
189	    // Only claim clearly-upward drags; leave taps and downward scrolling to
190	    // the text input, and mostly-horizontal drags to the navigator's
191	    // full-screen back swipe (Capture screen options in App.tsx). The ±48
192	    // fail zone is deliberately wider than the -24 activation so a fast
193	    // diagonal swipe-up still files the page.
194	    .activeOffsetY([-24, Number.MAX_SAFE_INTEGER])
195	    .failOffsetX([-48, 48])
196	    .failOffsetY(12)
197	    .onUpdate((event) => {
198	      translateY.value = Math.min(0, event.translationY);
199	    })
200	    .onEnd((event) => {
201	      const shouldCommit =
202	        event.translationY < -SWIPE_DISTANCE || event.velocityY < SWIPE_VELOCITY;
203	      if (shouldCommit) {
204	        translateY.value = withTiming(
205	          -height,
206	          { duration: 200 },
207	          (finished) => {
208	            if (finished) {
209	              runOnJS(commitPage)();
210	            }
211	          }
212	        );
213	      } else {
214	        translateY.value = withSpring(0, { damping: 20, stiffness: 300 });
215	      }
216	    });
217	
218	  const pageStyle = useAnimatedStyle(() => ({
219	    transform: [{ translateY: translateY.value }],
220	  }));
221	
222	  const toolbarStyle = useAnimatedStyle(() => ({
223	    opacity: iconsOpacity.value,
224	  }));
225	
226	  const onChange = (value: string) => {
227	    setText(value);
228	    session.onChange(value);
229	    // Keep the page uncluttered while writing; tapping back into the text
230	    // brings the hamburger/mic buttons back. While a dictation is running the
231	    // stop button must stay reachable, so nothing fades.
232	    if (iconsVisible && !recordingActive) {
233	      hideIcons();
234	    }
235	  };
236	
237	  return (
238	    <View style={[styles.root, { backgroundColor: theme.colors.background }]}>
239	      <Animated.View style={[styles.depth, syncDepthStyle]}>
240	      <GestureDetector gesture={Gesture.Race(pan, dismissKeyboardPan, swipeToSync)}>
241	        <Animated.View
242	          style={[
243	            styles.page,
244	            { backgroundColor: theme.colors.background, paddingTop: insets.top + 12 },
245	            pageStyle,
246	          ]}
247	        >
248	          <TextInput
249	            key={pageKey}
250	            ref={inputRef}
251	            style={[styles.input, { color: theme.colors.text }]}
252	            value={text}
253	            onChangeText={onChange}
254	            onPressIn={showIcons}
255	            placeholder="Start typing…"
256	            placeholderTextColor={theme.colors.secondaryText}
257	            multiline
258	            scrollEnabled
259	            textAlignVertical="top"
260	            keyboardAppearance={theme.dark ? "dark" : "light"}
261	          />
262	          {/* "swipe up for a new page" hint hidden per feedback — the gesture
263	              still works, we just don't want to show the label. */}
264	        </Animated.View>
265	      </GestureDetector>
266	
267	      <Animated.View
268	        pointerEvents={iconsVisible ? "auto" : "none"}
269	        style={[styles.toolbarLeft, { top: insets.top + 8 }, toolbarStyle]}
270	      >
271	        <ToolbarButton
272	          icon="menu-outline"
273	          // popTo, not navigate: the menu is the stack root below this
274	          // screen, and v7 navigate would push a second Menu on top (sliding
275	          // in from the right) instead of popping back to it.
276	          onPress={() => navigation.popTo("Menu")}
277	        />
278	      </Animated.View>
279	      <Animated.View
280	        pointerEvents={iconsVisible ? "auto" : "none"}
281	        style={[styles.fab, { bottom: insets.bottom + 36 }, toolbarStyle]}
282	      >
283	        <DictationButton onRecordingChange={setRecordingActive} />
284	      </Animated.View>
285	      </Animated.View>
286	
287	      {/* Native-push depth cues for the sync swipe: the page dims while the
288	          sync preview rides in above it (see swipeToSync). */}
289	      <Animated.View
290	        pointerEvents="none"
291	        style={[StyleSheet.absoluteFill, styles.syncDim, syncDimStyle]}
292	      />
293	      <Animated.View
294	        pointerEvents="none"
295	        style={[
296	          styles.syncPreview,
297	          { backgroundColor: theme.colors.background },
298	          syncPreviewStyle,
299	        ]}
300	      >
301	        {/* Replica of Sync's native header (title + chevron-only back) so
302	            the instant swap after commit only pops the body in. */}
303	        <View style={{ paddingTop: insets.top }}>
304	          <View style={styles.syncPreviewBar}>
305	            <Ionicons
306	              name="chevron-back"
307	              size={26}
308	              color={theme.colors.text}
309	              style={styles.syncPreviewBack}
310	            />
311	            <Text style={[styles.syncPreviewTitle, { color: theme.colors.text }]}>
312	              Sync
313	            </Text>
314	          </View>
315	        </View>
316	      </Animated.View>
317	    </View>
318	  );
319	};
320	
321	const styles = StyleSheet.create({
322	  root: { flex: 1 },
323	  depth: { flex: 1 },
324	  syncDim: { backgroundColor: "#000" },
325	  syncPreview: {
326	    position: "absolute",
327	    top: 0,
328	    left: 0,
329	    right: 0,
330	    bottom: 0,
331	    shadowColor: "#000",
332	    shadowOffset: { width: -4, height: 0 },
333	    shadowOpacity: 0.12,
334	    shadowRadius: 10,
335	  },
336	  // Mirrors the native-stack header: 44pt bar, centered 17pt semibold title,
337	  // chevron-only back at the left edge.
338	  syncPreviewBar: { height: 44, alignItems: "center", justifyContent: "center" },
339	  syncPreviewBack: { position: "absolute", left: 8, top: 9 },
340	  syncPreviewTitle: { fontSize: 17, fontWeight: "600" },
341	  page: { flex: 1, paddingHorizontal: 20 },
342	  input: {
343	    flex: 1,
344	    fontSize: 17,
345	    lineHeight: 26,
346	    paddingTop: 44,
347	  },
348	  fab: {
349	    position: "absolute",
350	    right: 32,
351	    alignItems: "flex-end",
352	  },
353	  toolbarLeft: {
354	    position: "absolute",
355	    left: 20,
356	    flexDirection: "row",
357	  },
358	});
