1	// The app menu — the root of the stack: close button + Feed / Folders tabs
2	// on top (inline note + folder lists), Sync and Settings pinned at the
3	// bottom. The capture page sits pushed above it, so its hamburger or a
4	// swipe-back pops here; the close button pushes a fresh capture page back
5	// in, and a leftward swipe anywhere drags a preview of it in with the finger
6	// (see swipeToCapture below). Everything else is pushed from here, so
7	// swipe-back from Sync/Settings/Folder/Editor lands back on the menu.
8	
9	import { Ionicons } from "@expo/vector-icons";
10	import { CommonActions, useNavigation } from "@react-navigation/native";
11	import type { NativeStackNavigationProp } from "@react-navigation/native-stack";
12	import { useEffect, useState } from "react";
13	import {
14	  FlatList,
15	  InteractionManager,
16	  Pressable,
17	  SectionList,
18	  StyleSheet,
19	  Text,
20	  useWindowDimensions,
21	  View,
22	} from "react-native";
23	import { Gesture, GestureDetector } from "react-native-gesture-handler";
24	import Animated, {
25	  Easing,
26	  runOnJS,
27	  useAnimatedStyle,
28	  useSharedValue,
29	  withTiming,
30	} from "react-native-reanimated";
31	import { useSafeAreaInsets } from "react-native-safe-area-context";
32	
33	import { FEED_FOLDER_PATH } from "@typenotes/shared/constants";
34	
35	import {
36	  browsableFolders,
37	  findFolder,
38	  folderNoteRows,
39	  groupNoteRowsByDate,
40	} from "../lib/feed";
41	import { formatRelativeTime } from "../lib/relative-time";
42	import type { RootStackParamList } from "../navigation";
43	import { useNotesStore } from "../state/notes-store";
44	import { useSyncStore } from "../state/sync-store";
45	import { useTheme } from "../theme";
46	import { ToolbarButton } from "../ui/toolbar-button";
47	import { NoteListRow } from "./feed-screen";
48	
49	type MenuTab = "feed" | "folders";
50	
51	// Releasing the drag past this fraction of the screen (or flicking faster
52	// than this, px/s leftward) commits to the capture page.
53	const OPEN_CAPTURE_PROGRESS = 0.3;
54	const OPEN_CAPTURE_VELOCITY = -500;
55	// How far the menu slides left behind the incoming page — the depth effect
56	// of a native iOS push.
57	const MENU_PARALLAX = 0.3;
58	
59	export const MenuScreen = () => {
60	  const theme = useTheme();
61	  const insets = useSafeAreaInsets();
62	  const navigation =
63	    useNavigation<NativeStackNavigationProp<RootStackParamList>>();
64	  const { width } = useWindowDimensions();
65	  const [tab, setTab] = useState<MenuTab>("feed");
66	
67	  const tree = useNotesStore((s) => s.tree);
68	  const previews = useNotesStore((s) => s.previews);
69	
70	  // 0..1 — how far the capture-page preview has slid in over the menu.
71	  // Driven on the UI thread by the pan below; at 1 the real Capture screen
72	  // is pushed underneath it with animation:none (there is no native
73	  // interactive *push* gesture, so this hand-rolls one — the preview is a
74	  // pixel replica of the blank capture page, and the swap is invisible).
75	  const captureProgress = useSharedValue(0);
76	
77	  const menuDepthStyle = useAnimatedStyle(() => ({
78	    transform: [{ translateX: -width * MENU_PARALLAX * captureProgress.value }],
79	  }));
80	  const dimStyle = useAnimatedStyle(() => ({
81	    opacity: 0.08 * captureProgress.value,
82	  }));
83	  const capturePreviewStyle = useAnimatedStyle(() => ({
84	    transform: [{ translateX: width * (1 - captureProgress.value) }],
85	    // At rest the preview sits exactly one screen-width to the right — but
86	    // during a native pop the whole menu view (preview included) slides in
87	    // from -30% parallax, which would poke the preview's left edge (its
88	    // hamburger replica) into the top-right of the frame. Hide it whenever
89	    // the menu's own gesture isn't driving it.
90	    opacity: captureProgress.value > 0 ? 1 : 0,
91	  }));
92	
93	  // RNGH's pan activating does not reliably cancel React Native's own
94	  // responder (and by claiming the gesture it also keeps the lists' scroll
95	  // from doing that cancelling), so a swipe that starts on a row/button can
96	  // still fire its onPress on release. A genuine tap never moves the pan, so
97	  // any preview progress at press time means the touch was a swipe: drop it.
98	  const pressWasSwipe = () => captureProgress.value > 0.001;
99	
100	  const openScreen = <Screen extends keyof RootStackParamList>(
101	    screen: Screen,
102	    params?: RootStackParamList[Screen]
103	  ) => {
104	    if (pressWasSwipe()) {
105	      return;
106	    }
107	    navigation.dispatch(CommonActions.navigate({ name: screen, params }));
108	  };
109	
110	  const selectTab = (next: MenuTab) => {
111	    if (!pressWasSwipe()) {
112	      setTab(next);
113	    }
114	  };
115	
116	  const openCapture = () => {
117	    if (pressWasSwipe()) {
118	      return;
119	    }
120	    navigation.navigate("Capture");
121	  };
122	  const openCaptureBehindPreview = () => {
123	    navigation.navigate("Capture", { instant: true });
124	    // Drop the preview once the pushed screen is attached on top of the
125	    // menu. There is no native "attached" signal with animation:none; the
126	    // delay just has to outlive the mount, and only a back swipe started
127	    // within it could glimpse the reset.
128	    setTimeout(() => {
129	      captureProgress.value = 0;
130	    }, 400);
131	  };
132	
133	  // The whole menu is the gesture surface: a clearly-leftward drag anywhere
134	  // (16px of horizontal travel) pulls the capture-page preview in with the
135	  // finger. Presses under the swipe are filtered by pressWasSwipe above;
136	  // vertical drags fail fast and stay with the note/folder lists.
137	  const swipeToCapture = Gesture.Pan()
138	    .activeOffsetX(-16)
139	    .failOffsetX(24)
140	    .failOffsetY([-20, 20])
141	    .onUpdate((event) => {
142	      captureProgress.value = Math.min(
143	        1,
144	        Math.max(0, -event.translationX / width)
145	      );
146	    })
147	    .onEnd((event) => {
148	      const shouldOpen =
149	        captureProgress.value > OPEN_CAPTURE_PROGRESS ||
150	        event.velocityX < OPEN_CAPTURE_VELOCITY;
151	      if (shouldOpen) {
152	        captureProgress.value = withTiming(
153	          1,
154	          { duration: 160, easing: Easing.out(Easing.cubic) },
155	          (finished) => {
156	            if (finished) {
157	              runOnJS(openCaptureBehindPreview)();
158	            }
159	          }
160	        );
161	      } else {
162	        captureProgress.value = withTiming(0, { duration: 180 });
163	      }
164	    });
165	
166	  const lastSyncedMs = useSyncStore((s) => s.history[0]?.authored_ms ?? null);
167	
168	  // Boot pushes Capture on top of the menu in the same first React commit,
169	  // so building the note/folder lists here would sit on the app's
170	  // first-paint path. Render an empty page for the first tick and fill in
171	  // right after — done long before a swipe can reveal the menu.
172	  const [contentReady, setContentReady] = useState(false);
173	  useEffect(() => {
174	    const task = InteractionManager.runAfterInteractions(() => setContentReady(true));
175	    return () => task.cancel();
176	  }, []);
177	  if (!contentReady) {
178	    return <View style={[styles.root, { backgroundColor: theme.colors.background }]} />;
179	  }
180	
181	  const feedRows = folderNoteRows(findFolder(tree, FEED_FOLDER_PATH), previews);
182	  const feedSections = groupNoteRowsByDate(feedRows);
183	  const folders = browsableFolders(findFolder(tree, ""));
184	
185	  return (
186	    <GestureDetector gesture={swipeToCapture}>
187	      <View style={[styles.root, { backgroundColor: theme.colors.background }]}>
188	        <Animated.View
189	          style={[
190	            styles.menuContent,
191	            { paddingTop: insets.top + 8, paddingBottom: insets.bottom + 8 },
192	            menuDepthStyle,
193	          ]}
194	        >
195	        <View style={styles.topBar}>
196	          <ToolbarButton icon="close-outline" onPress={openCapture} />
197	        </View>
198	
199	        <View style={[styles.tabs, { backgroundColor: theme.colors.surface }]}>
200	          <TabButton label="Feed" active={tab === "feed"} onPress={() => selectTab("feed")} />
201	          <TabButton
202	            label="Folders"
203	            active={tab === "folders"}
204	            onPress={() => selectTab("folders")}
205	          />
206	        </View>
207	
208	        {tab === "feed" ? (
209	          <SectionList
210	            style={styles.list}
211	            sections={feedSections}
212	            keyExtractor={(row) => row.path}
213	            stickySectionHeadersEnabled
214	            renderSectionHeader={({ section }) => (
215	              <View style={[styles.sectionHeader, { backgroundColor: theme.colors.background }]}>
216	                <Text style={[styles.sectionHeaderText, { color: theme.colors.secondaryText }]}>
217	                  {section.title}
218	                </Text>
219	              </View>
220	            )}
221	            renderItem={({ item }) => (
222	              <NoteListRow
223	                row={item}
224	                theme={theme}
225	                onPress={() =>
226	                  openScreen("Editor", {
227	                    path: item.path,
228	                    title: item.preview.title || "Note",
229	                  })
230	                }
231	              />
232	            )}
233	            ListEmptyComponent={
234	              <Text style={[styles.empty, { color: theme.colors.secondaryText }]}>
235	                No notes yet — swipe left and start typing.
236	              </Text>
237	            }
238	          />
239	        ) : (
240	          <FlatList
241	            style={styles.list}
242	            data={folders}
243	            keyExtractor={(folder) => folder.path}
244	            renderItem={({ item }) => (
245	              <Pressable
246	                onPress={() => openScreen("Folder", { path: item.path, title: item.name })}
247	                style={({ pressed }) => [
248	                  styles.folderRow,
249	                  { borderBottomColor: theme.colors.border, opacity: pressed ? 0.6 : 1 },
250	                ]}
251	              >
252	                <Text style={[styles.folderName, { color: theme.colors.text }]}>
253	                  {item.name}
254	                </Text>
255	                <Text style={[styles.folderMeta, { color: theme.colors.secondaryText }]}>
256	                  {item.notes.length > 0 ? `${item.notes.length}` : ""} ›
257	                </Text>
258	              </Pressable>
259	            )}
260	            ListEmptyComponent={
261	              <Text style={[styles.empty, { color: theme.colors.secondaryText }]}>
262	                No folders yet.
263	              </Text>
264	            }
265	          />
266	        )}
267	
268	        {/* App-level destinations, visually set apart from the note/folder
269	            rows by the grouped card (same surface treatment as the tabs). */}
270	        <View style={[styles.bottom, { backgroundColor: theme.colors.surface }]}>
271	          <BottomItem
272	            icon="sync-outline"
273	            label="Sync"
274	            subtitle={`Last synced ${formatRelativeTime(lastSyncedMs)}`}
275	            onPress={() => openScreen("Sync")}
276	          />
277	          <View style={[styles.bottomSeparator, { backgroundColor: theme.colors.border }]} />
278	          <BottomItem
279	            icon="settings-outline"
280	            label="Settings"
281	            onPress={() => openScreen("Settings")}
282	          />
283	        </View>
284	        </Animated.View>
285	
286	        {/* Native-push depth cues: the menu dims while the preview page
287	            rides in above it, casting a shadow over the seam. */}
288	        <Animated.View
289	          pointerEvents="none"
290	          style={[StyleSheet.absoluteFill, styles.dim, dimStyle]}
291	        />
292	        <Animated.View
293	          pointerEvents="none"
294	          style={[
295	            styles.capturePreview,
296	            { backgroundColor: theme.colors.background },
297	            capturePreviewStyle,
298	          ]}
299	        >
300	          <Text
301	            style={[
302	              styles.previewPlaceholder,
303	              { color: theme.colors.secondaryText, marginTop: insets.top + 56 },
304	            ]}
305	          >
306	            Start typing…
307	          </Text>
308	          <View
309	            style={[
310	              styles.previewButton,
311	              {
312	                left: 20,
313	                top: insets.top + 8,
314	                backgroundColor: theme.colors.surface,
315	                borderColor: theme.colors.border,
316	              },
317	            ]}
318	          >
319	            <Ionicons name="menu-outline" size={20} color={theme.colors.text} />
320	          </View>
321	          <View
322	            style={[
323	              styles.previewButton,
324	              styles.previewMic,
325	              {
326	                right: 32,
327	                bottom: insets.bottom + 36,
328	                backgroundColor: theme.colors.surface,
329	                borderColor: theme.colors.border,
330	              },
331	            ]}
332	          >
333	            <Ionicons name="mic-outline" size={22} color={theme.colors.text} />
334	          </View>
335	        </Animated.View>
336	      </View>
337	    </GestureDetector>
338	  );
339	};
340	
341	const TabButton = ({
342	  label,
343	  active,
344	  onPress,
345	}: {
346	  label: string;
347	  active: boolean;
348	  onPress: () => void;
349	}) => {
350	  const theme = useTheme();
351	  return (
352	    <Pressable
353	      onPress={onPress}
354	      style={({ pressed }) => [
355	        styles.tab,
356	        {
357	          backgroundColor: active ? theme.colors.background : "transparent",
358	          opacity: pressed ? 0.7 : 1,
359	        },
360	      ]}
361	    >
362	      <Text
363	        style={[
364	          styles.tabLabel,
365	          { color: active ? theme.colors.text : theme.colors.secondaryText },
366	        ]}
367	      >
368	        {label}
369	      </Text>
370	    </Pressable>
371	  );
372	};
373	
374	const BottomItem = ({
375	  icon,
376	  label,
377	  subtitle,
378	  onPress,
379	}: {
380	  icon: keyof typeof Ionicons.glyphMap;
381	  label: string;
382	  subtitle?: string;
383	  onPress: () => void;
384	}) => {
385	  const theme = useTheme();
386	  return (
387	    <Pressable
388	      onPress={onPress}
389	      style={({ pressed }) => [styles.bottomItem, { opacity: pressed ? 0.6 : 1 }]}
