396	            {subtitle}
397	          </Text>
398	        ) : null}
399	      </View>
400	      <Text style={{ color: theme.colors.secondaryText }}>›</Text>
401	    </Pressable>
402	  );
403	};
404	
405	const styles = StyleSheet.create({
406	  root: { flex: 1 },
407	  menuContent: { flex: 1 },
408	  dim: { backgroundColor: "#000" },
409	  capturePreview: {
410	    position: "absolute",
