412	    left: 0,
413	    right: 0,
414	    bottom: 0,
415	    shadowColor: "#000",
416	    shadowOffset: { width: -4, height: 0 },
417	    shadowOpacity: 0.12,
418	    shadowRadius: 10,
419	  },
420	  // The preview mirrors the blank capture page (capture-screen.tsx): page
421	  // padding top +12 / horizontal 20, input paddingTop 44, 17pt text, and the
422	  // toolbar circle geometry from ToolbarButton / DictationButton.
423	  previewPlaceholder: { paddingHorizontal: 20, fontSize: 17, lineHeight: 26 },
424	  previewButton: {
425	    position: "absolute",
426	    width: 38,
427	    height: 38,
428	    borderRadius: 19,
429	    borderWidth: StyleSheet.hairlineWidth,
430	    alignItems: "center",
431	    justifyContent: "center",
432	  },
433	  previewMic: { width: 44, height: 44, borderRadius: 22 },
434	  topBar: {
435	    flexDirection: "row",
436	    justifyContent: "flex-end",
437	    paddingHorizontal: 16,
438	    marginBottom: 12,
439	  },
440	  tabs: {
441	    flexDirection: "row",
442	    marginHorizontal: 12,
443	    marginBottom: 8,
444	    borderRadius: 10,
445	    padding: 3,
446	    gap: 3,
447	  },
448	  tab: {
449	    flex: 1,
450	    borderRadius: 8,
451	    paddingVertical: 8,
452	    alignItems: "center",
453	  },
454	  tabLabel: { fontSize: 14, fontWeight: "600" },
