468	  folderMeta: { fontSize: 13 },
469	  bottom: {
470	    marginHorizontal: 12,
471	    marginTop: 8,
472	    borderRadius: 12,
473	    overflow: "hidden",
474	  },
475	  bottomSeparator: {
476	    height: StyleSheet.hairlineWidth,
477	    marginLeft: 46,
478	  },
479	  bottomItem: {
480	    flexDirection: "row",
481	    alignItems: "center",
