1	import {
2	  CommonActions,
3	  createNavigationContainerRef,
4	  useNavigation,
5	  useRoute,
6	  type RouteProp,
7	} from "@react-navigation/native";
8	import {
9	  createNativeStackNavigator,
10	  type NativeStackNavigationProp,
11	} from "@react-navigation/native-stack";
12	import { useEffect } from "react";
13	
14	// One native stack, with the menu as its root — conceptually the menu sits to
15	// the LEFT of the capture page and the sync screen to its RIGHT. The app
16	// boots with Capture pushed on top of Menu (see initialState in App.tsx), so
17	// the native swipe-back on the capture page reveals the menu; a leftward
18	// swipe on the menu drags a capture preview back in, and a leftward swipe on
19	// the capture page pushes Sync (swipe-back there lands on capture again).
20	// Every other screen is pushed from the menu so swipe-back walks naturally
21	// back to it.
22	export type RootStackParamList = {
23	  Menu: undefined;
24	  // `instant` skips the push animation: a gesture-driven preview has already
25	  // animated the page in (menu → capture, capture → sync), so the real
26	  // screen must appear underneath it without animating a second time.
27	  Capture: { instant?: boolean } | undefined;
28	  Feed: undefined;
29	  Folder: { path: string; title: string };
30	  Editor: { path: string; title?: string };
31	  Sync: { instant?: boolean } | undefined;
32	  Settings: undefined;
33	  SettingsWorkingFolders: undefined;
34	  SettingsTranscription: undefined;
35	};
36	
37	export const Stack = createNativeStackNavigator<RootStackParamList>();
38	
39	/** Container ref so deep-link handling can navigate from outside React. */
40	export const navigationRef = createNavigationContainerRef<RootStackParamList>();
41	
42	export const navigateToScreen = <Screen extends keyof RootStackParamList>(
43	  screen: Screen,
44	  params?: RootStackParamList[Screen]
45	) => {
46	  if (navigationRef.isReady()) {
47	    navigationRef.dispatch(CommonActions.navigate({ name: screen, params }));
48	  }
49	};
50	
51	/**
52	 * For screens that can be pushed with `instant: true` (their transition was
53	 * already played by a gesture-driven preview, so the real push used
